from pathlib import Path
import json,re
p=Path(__file__).parent/'theme'
def edit(name,fn):
 f=p/'sections'/f'{name}.liquid';f.write_text(fn(f.read_text(encoding='utf-8')),encoding='utf-8')
def css(name,rules):
 edit(name,lambda s:s.replace('{% schema %}','<!-- Mobile visual repair: 6 October 2026 -->\n<style>\n@media(max-width:749px){'+rules+'}\n</style>\n{% schema %}',1))
css('june-make-room','''.jh .jh__actions{flex-direction:row;flex-wrap:wrap;align-items:center;gap:4px 12px}.jh .jh__actions .jh__button{flex:1;min-width:140px;padding-inline:14px}.jh .jh__actions .jh__text-link{flex:1;min-width:140px;text-align:center}.jh .jh__panel[data-panel=undated] .jh__actions{gap:4px 12px}.jh .jh__panel[data-panel=undated] .jh__art,.jh .jh__panel[data-panel=limited] .jh__limited-background{height:220px}.jh .jh__tab{justify-content:flex-start;min-height:92px;gap:6px}.jh .jh__tab>span{min-height:38px;display:flex;flex-direction:column;justify-content:center}.jh .jh__life-list{margin-top:8px}.jh .jh__life-item{min-height:78px}''')
edit('june-make-room',lambda s:s.replace("loading: 'lazy', alt: section.settings.limited_alt","loading: 'eager', alt: section.settings.limited_alt"))
css('june-your-year','''.ju .ju__buy>.ju__policies{display:flex!important;gap:0 20px;flex-wrap:wrap}.ju .ju__policies a{min-height:44px;flex:none}.ju .ju__thumbs{gap:8px;margin:0 0 4px}.ju .ju__thumbs button{width:44px;height:44px;border-radius:50%;padding:10px}.ju .ju__thumbs img{display:none}.ju .ju__thumbs button:after{content:"";display:block;width:9px;height:9px;margin:auto;border-radius:50%;background:currentColor;opacity:.3}.ju .ju__thumbs button[aria-pressed=true]:after{opacity:1}.ju .ju__panel{grid-template-columns:minmax(130px,.95fr) minmax(0,1fr);gap:12px;padding-block:14px}.ju .ju__preview{height:180px}.ju .ju__buy{gap:4px;padding-bottom:8px}.ju .ju__toggles{flex-wrap:wrap;gap:4px}.ju .ju__inside-copy{align-self:center}''')
css('june-with-extras','''.jl .jl__mobile-products .jl__planner{height:180px!important}.jl .jl__stamp{width:58px;height:58px;right:-3%;font-size:7px!important}.jl .jl__stamp strong{font-size:22px}.jl .jl__product-heads{min-height:0}.jl .jl__header .jl__reveal{box-shadow:none;background:transparent;border:0;text-decoration:underline;padding:0;min-height:44px;margin-top:4px}.jl .jl__invitation{margin-top:10px}.jl .jl__gift{flex-basis:72%;width:72%;max-width:none}.jl .jl__gifts-stage{gap:12px;scroll-padding-inline:20px}.jl .jl__swipe{font-weight:600}.jl .jl__policies{display:flex!important;gap:0 20px}''')
css('june-next-chapter','''.jn.jn--portal .jn__portal-scene{height:240px;max-width:290px;margin:8px auto 12px}.jn.jn--portal .jn__portal-year{gap:12px;padding-top:12px}.jn.jn--portal .jn__year{font-size:min(calc(var(--jn-year-mobile)*1.5),25vw)}.jn.jn--portal .jn__light-spill{height:55px}.jn.jn--portal .jn__signup{font-size:calc(var(--jn-signup-mobile)*.72);margin-bottom:8px}.jn.jn--portal .jn__layout{gap:12px!important}''')
css('june-inside-discovery','''.ji .ji__tabs{display:flex;overflow-x:auto;gap:4px;scroll-snap-type:x proximity}.ji .ji__tab{flex:1;min-width:78px;white-space:nowrap;min-height:48px;padding:8px 6px;scroll-snap-align:start}.ji .ji__images{height:250px!important}.ji .ji__descriptions{min-height:0;padding-block:8px}.ji .ji__shown{line-height:1.4;margin-top:6px}.ji .ji__controls{padding-bottom:16px!important}''')
css('june-other-chapters','''.jcs[data-pinned=true] .jcs__scene{justify-content:flex-start;padding-top:max(78px,calc(var(--jcs-height)*.12));gap:14px}.jcs .jcs__skip{right:12px;top:10px;padding:10px 14px}''')
edit('june-other-chapters',lambda s:s.replace('this.durations=[blank,1.1,2,.8,blank','this.durations=[mobile?Math.min(blank,.2):blank,1.1,2,.8,blank'))
css('june-shop-the-corner','''.jcorner .jcorner__hotspots{display:none}.jcorner .jcorner__item{grid-template-columns:1fr!important;gap:14px}.jcorner .jcorner__item june-photo-viewer{width:100%;height:240px}.jcorner .jcorner__item>div{width:100%}.jcorner .jcorner__item .jcorner__link{min-height:44px;margin-top:8px}.jcorner .jcorner__nav{gap:8px}.jcorner .jcorner__canvas{max-height:230px;overflow:hidden}''')
edit('june-find-your-glow',lambda s:s.replace("{% if block.settings.mobile_scene != blank %}<source media=\"(max-width:749px)\" srcset=\"{{ block.settings.mobile_scene | image_url: width: 900 }}\">{% endif %}","{% assign mobile_scene = block.settings.mobile_scene | default: block.settings.product.featured_image %}{% if mobile_scene != blank %}<source media=\"(max-width:749px)\" srcset=\"{{ mobile_scene | image_url: width: 900 }}\">{% endif %}"))
css('june-find-your-glow','''.jglow.jglow{min-height:0;background:#14110e}.jglow .jglow__stage{min-height:490px}.jglow .jglow__header{padding:24px 20px 12px}.jglow .jglow__scenes,.jglow .jglow__backdrop{top:190px;bottom:auto;height:300px}.jglow .jglow__scene picture{height:100%}.jglow .jglow__scene img,.jglow .jglow__backdrop img{object-fit:contain;object-position:center}.jglow:after{display:none}.jglow .jglow__dock{margin:0;padding:16px 20px;border-inline:0;border-bottom:0;border-radius:0;background:#14110e}.jglow .jglow__choice{min-height:100px}.jglow .jglow__choice img{width:88px;height:72px;object-fit:contain}.jglow .jglow__choice[aria-pressed=true]{border-bottom:3px solid var(--jglow-accent)}.jglow .jglow__details{margin-top:8px;padding-top:12px}''')
css('june-pick-your-pour','''.jg .jg__header{min-height:0;padding-top:20px}.jg .jg__heading{font-size:calc(var(--jg-heading-mobile)*.86)}.jg .jg__scenes{height:min(var(--jg-mobile-height),290px)}.jg .jg__tab{display:flex;align-items:center;justify-content:center;min-height:52px}.jg.jg .jg__product{min-height:0;gap:8px}.jg .jg__footer{gap:10px;padding-bottom:0}.jg .jg__details{margin-bottom:0}.jg .jg__all{margin-top:0}.jg .jg__details>div{position:static;width:100%;box-shadow:none}.jg .jg__details[open]{width:100%}''')
css('june-layer-the-table','''.jt .jt__products>[data-product]{display:flex;flex-direction:column;gap:6px}.jt .jt__original{width:100%;height:220px;align-self:stretch;margin:0 0 8px}.jt .jt__product-name,.jt .jt__price{margin:0}.jt .jt__primary{width:100%;margin-top:6px}.jt .jt__modes{gap:8px}.jt .jt__modes button{min-height:44px}.jt .jt__footer{flex-direction:row;flex-wrap:wrap;gap:0 18px;justify-content:flex-start}.jt .jt__secondary{justify-content:flex-start}.jt .jt__hint{margin-bottom:8px}''')
css('june-a-little-curious','''.jmystery .jmystery__offer>.jmystery__price{display:none}.jmystery .jmystery__peek{margin-top:12px}.jmystery .jmystery__tiers a{position:relative;padding-right:26px;min-height:58px}.jmystery .jmystery__tiers a:after{content:"↗";position:absolute;right:0}.jmystery .jmystery__visual{margin-bottom:8px}''')
css('june-footer','''.jfooter .jfooter__brand{font-size:min(var(--jfooter-brand-mobile),8.8vw);white-space:nowrap;letter-spacing:-.04em;padding-block:20px}.jfooter .jfooter__pay-badge svg{display:none}.jfooter .jfooter__pay-badge{min-height:36px}''')
css('my-header','''#TjsPremiumHeader-{{ section.id }} .tjs-ph__search-wrap.is-search-active{grid-template-rows:auto auto}#TjsPremiumHeader-{{ section.id }} .tjs-ph__search-wrap.is-search-active .tjs-ph__predictive{height:auto;max-height:calc(100dvh - 90px);align-self:start}''')
# Correct configured product overrides, preserving every unrelated merchant setting.
f=p/'templates/index.json';s=f.read_text(encoding='utf-8');prefix=s[:s.index('{')];d=json.loads(s[s.index('{'):])
for sec in d['sections'].values():
 if sec['type']=='june-other-chapters':sec['settings']['skip']='Skip to shopping'
 if sec['type']=='june-shop-the-corner':
  for b in sec.get('blocks',{}).values():
   if b['type']=='piece':
    b['settings']['name']='';b['settings']['specification']='';b['settings']['short_label']={'fleur-de-luxe-floral-sticks-set-of-2':'Floral sticks','giraffe-on-unicycle-figurine':'Giraffe','leandre-ornamental-artifact':'Artifact'}.get(b['settings'].get('product'),'Décor')
 if sec['type']=='june-pick-your-pour':
  for b in sec.get('blocks',{}).values():
   if b['type']=='pour' and b['settings'].get('product') in ['ripple-coffee-mug-with-lid-spoon','cocktail-glass']:
    b['settings']['name']='';b['settings']['detail']='';b['settings']['specification']=''
    if b['settings']['product']=='ripple-coffee-mug-with-lid-spoon':
     b['settings']['image']='';b['settings']['mobile_image']='';b['settings']['image_number']=1;b['settings']['foreground_mask']=''
f.write_text(prefix+json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Mobile changes prepared')
